import{z as i,x as S,o as e,c as B,q as o,j as r,D as E,d as s,s as l,S as n,b as t}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"DNSSEC","description":"","frontmatter":{"title":"DNSSEC","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dnssec.md","filePath":"cs/dnssec.md","lastUpdated":1791063341000}'),A={name:"cs/dnssec.md"};function d(p,a,C,c,N,h){const D=S("Mermaid");return e(),B("div",null,[a[2]||(a[2]=o('<h1 id="dnssec" tabindex="-1">DNSSEC <a class="header-anchor" href="#dnssec" aria-label="Permalink to &quot;DNSSEC&quot;">​</a></h1><div class="epigraph"><p>权威用私钥签 RRSET，解析器沿 DS 链到根信任锚验证；防篡改与伪造，不加密查询。</p><footer>—— 据 RFC 4033 / 4034 / 4035 DNSSEC 整理</footer></div><p><a href="/cs/dns-cache-ttl">上一课</a> 的缓存可被毒化。主干 DNS 无认证。<a href="/cs/bgp-hijack-rpki">RPKI</a> 是路由侧同类问题。缺口是 <strong>DNSSEC</strong>：RRSIG、DNSKEY、DS、AD 位。本课不把 DoH 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>UDP 查询易被伪造应答（缓存中毒）。DNSSEC：区签名，父区 DS 钉子区密钥，直到根。验证失败应 SERVFAIL，不能「软失败当没开」。NSEC/NSEC3 证明不存在。不提供机密：嗅探仍可见问了谁——下一课 DoH/DoT。与 RPKI 对照：都是 PKI 钉源，验证的对象是 DNS 节点 vs 前缀。</p><p><span class="marginnote">术语翻译：DS 记录是父区在孩子区门口贴的「密钥指纹条」——存的是孩子 DNSKEY 的哈希。解析器拿它对照孩子交出的真密钥，指纹对上才敢用这把钥验签名；根公钥则出厂就装在解析器里，当信任起点。</span></p><p>不要把 DNSSEC 写成让域名变安全浏览的全部。</p><p><span class="marginnote">RFC 4033–4035。密钥轮换与算法是运营。本课不写攻击步骤。</span></p><h3 id="完整性不是机密" tabindex="-1">完整性不是机密 <a class="header-anchor" href="#完整性不是机密" aria-label="Permalink to &quot;完整性不是机密&quot;">​</a></h3><p>链到根锚，失败应硬失败。不加密 QNAME。密钥轮换要时钟大致对。报文变大易截断。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：根锚 → TLD DS → 区 DNSKEY → RRSIG。对照 TLS：TLS 保护信道，DNSSEC 保护 DNS 数据。Cookie 无补。</p>',12)),(e(),r(n,null,{default:E(()=>[l(D,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20ANCH%5B%22%E6%A0%B9%E4%BF%A1%E4%BB%BB%E9%94%9A%22%5D%20--%3E%20DS%5B%22DS%20%E9%93%BE%22%5D%0A%20%20DS%20--%3E%20KEY%5B%22%E5%8C%BA%20DNSKEY%22%5D%0A%20%20KEY%20--%3E%20SIG%5B%22RRSIG%20%E8%A6%86%E7%9B%96%20RRSET%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[s("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"报文变大，易截断改 TCP，与 PMTUD 互动。TTL 内签名必须有效，时钟要大致对——后课 NTP。解析器 CPU 验签，放大攻击要限。CDN 多权威要共享或分签。",-1)),(e(),r(n,null,{default:E(()=>[l(D,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E6%94%B6%E5%88%B0%E5%BA%94%E7%AD%94%E4%B8%8E%20RRSIG%22%5D%20--%3E%20GETK%5B%22%E5%8F%96%E5%87%BA%E5%8C%BA%20DNSKEY%20%E4%B8%8E%E7%88%B6%E5%8C%BA%20DS%22%5D%0A%20%20GETK%20--%3E%20V%5B%22%E7%94%A8%20DS%20%E9%AA%8C%20DNSKEY%EF%BC%8C%E5%86%8D%E7%94%A8%20DNSKEY%20%E9%AA%8C%20RRSIG%22%5D%0A%20%20V%20--%3E%20OK%5B%22%E9%80%9A%E8%BF%87%EF%BC%9A%E7%BD%AE%20AD%20%E4%BD%8D%EF%BC%8C%E7%BC%93%E5%AD%98%E5%B9%B6%E8%BD%AC%E4%BA%A4%22%5D%0A%20%20V%20--%3E%20BAD%5B%22%E5%A4%B1%E8%B4%A5%EF%BC%9A%E8%BF%94%E5%9B%9E%20SERVFAIL%EF%BC%8C%E7%A1%AC%E5%A4%B1%E8%B4%A5%22%5D%0A%20%20BAD%20--%3E%20NOF%5B%22%E7%BB%9D%E4%B8%8D%E9%99%8D%E7%BA%A7%E4%B8%BA%E3%80%8E%E5%BD%93%E4%BD%9C%E6%B2%A1%E7%AD%BE%E5%90%8D%E3%80%8F%E7%BB%A7%E7%BB%AD%E7%94%A8%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=o('<p><span class="marginnote">数字实例：一条 RRSIG 本身就几百字节，签名后 A 记录应答常从一百来字节涨到上千字节，轻易越过 UDP 的 512 字节线，频繁「截断改 TCP」。这是 DNSSEC 普及慢的实际成本：每次验证更慢、也更容易碰上传输层问题。</span></p><p>AD 位仅当解析器已验；应用若自己验更端到端。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 DANE 的全部。DoH/DoT 是下一课。后课默认：DNSSEC 完整性与真实性；非机密。</p><p>部署断裂（父 DS 不配）比不开更伤，表现为解析失败。</p><p><span class="marginnote">常见误区：以为 DNSSEC 会加密查询、别人看不到你在访问哪个网站。它只保证「答案没被篡改、确实出自该区」，QNAME 全程明文可被中间人记录。机密要靠下一课的 DoH/DoT 把整条查询装进 TLS 信道。</span></p><p>下一课<a href="/cs/doh-dot">DoH / DoT</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>签名链到根锚，防伪造应答。</li><li>不加密查询内容。</li><li>失败应硬失败，勿降级。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 4033–4035。</li></ul>',9))])}const f=i(A,[["render",d]]);export{m as __pageData,f as default};
